const items = [];

for (const item of $input.all()) {
  try {
    const record = item.json.fields;

    const scopeItems = JSON.parse(record['Scope Items'] || '[]');
    const exclusions = JSON.parse(record['Exclusions'] || '[]');

    items.push({
      json: {
        success: true,
        session_id: record.session_id,
        scope_items: scopeItems,
        exclusions: exclusions,
        price: record.Price,
        timeline: record.Timeline,
        raw_input: record['Raw Input']
      }
    });
  } catch (error) {
    items.push({
      json: {
        success: false,
        error: error.message,
        raw_record: item.json
      }
    });
  }
}

return items;

const items = [];

for (const item of $input.all()) {
  try {
    const rawText = item.json.output;

    // jaga-jaga kalau Gemini masih wrap dalam ```json
    const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

    const parsed = JSON.parse(cleaned);

    items.push({
      json: {
        success: true,
        ...parsed
      }
    });
  } catch (error) {
    items.push({
      json: {
        success: false,
        error: error.message,
        raw_response: item.json.output || 'no output found'
      }
    });
  }
}

return items;

const items = [];

for (const item of $input.all()) {
  try {
    const rawText = item.json.output;

    const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

    const parsed = JSON.parse(cleaned);

    // validasi minimal - pastiin classification-nya salah satu dari 4 kategori yang valid
    const validClassifications = ['in-scope', 'out-of-scope', 'ambiguous', 'not-scope-related'];
    if (!validClassifications.includes(parsed.classification)) {
      throw new Error(`Invalid classification value: ${parsed.classification}`);
    }

    // ambiguous WAJIB punya clarifying_question, cek konsistensi
    if (parsed.classification === 'ambiguous' && !parsed.clarifying_question) {
      throw new Error('Classification ambiguous tapi clarifying_question kosong');
    }

    items.push({
      json: {
        success: true,
        ...parsed
      }
    });
  } catch (error) {
    items.push({
      json: {
        success: false,
        error: error.message,
        raw_response: item.json.output || 'no output found'
      }
    });
  }
}

return items;
